package com.zomiggy.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="otp_codes") public class OtpCode { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String mobile; @Column(nullable=false) private String code; @Column(nullable=false) private Instant expiresAt; @Column(nullable=false) private boolean used; protected OtpCode(){} public OtpCode(String mobile,String code){this.mobile=mobile;this.code=code;this.expiresAt=Instant.now().plusSeconds(30);} public boolean valid(String value){return !used&&!isExpired()&&code.equals(value);} public boolean isExpired(){return Instant.now().isAfter(expiresAt);} public void markUsed(){used=true;} public String getCode(){return code;} public String getMobile(){return mobile;} }